function startStage2(){stageContent.innerHTML='\n\n    <div class="card ecg-card">\n\n\n        <h1>\n            ❤️ ECG Monitoring\n        </h1>\n\n\n        <p class="stage-description">\n\n            Analyze the patient\'s heart rhythm\n            and identify the emergency condition.\n\n        </p>\n\n\n\n        <div class="monitor">\n\n\n            <div class="monitor-header">\n\n                HEART MONITOR\n\n            </div>\n\n\n\n            <div class="ecg-screen">\n\n\n                <div class="ecg-info">\n\n                    <span>\n                        BPM:\n                        <strong id="bpm">\n                            178\n                        </strong>\n                    </span>\n\n\n                    <span>\n                        Rhythm:\n                        <strong class="critical-text">\n                            UNSTABLE\n                        </strong>\n                    </span>\n\n                </div>\n\n\n\n                <svg\n                    class="ecg-wave"\n                    viewBox="0 0 600 150">\n\n\n                    <polyline\n\n                    points="\n                    0,80\n                    60,80\n                    90,80\n                    110,30\n                    130,120\n                    150,80\n                    220,80\n                    250,80\n                    270,35\n                    290,120\n                    310,80\n                    380,80\n                    420,80\n                    440,25\n                    460,125\n                    480,80\n                    600,80\n                    "\n\n                    />\n\n\n                </svg>\n\n\n\n            </div>\n\n\n\n\n            <div class="monitor-status">\n\n                Rhythm analysis required\n\n            </div>\n\n\n\n        </div>\n\n\n\n\n        <h3>\n\n            Select the detected rhythm:\n\n        </h3>\n\n\n\n        <div class="ecg-options">\n\n\n            <button\n                class="ecg-option"\n                data-answer="normal">\n\n                Normal Sinus Rhythm\n\n            </button>\n\n\n\n            <button\n                class="ecg-option"\n                data-answer="arrhythmia">\n\n                Ventricular Tachycardia\n\n            </button>\n\n\n\n            <button\n                class="ecg-option"\n                data-answer="flatline">\n\n                Flat Line\n\n            </button>\n\n\n        </div>\n\n\n\n        <div\n            id="ecg-status"\n            class="status-box">\n\n        </div>\n\n\n\n    </div>\n\n    ',beepLoop(),document.querySelectorAll(".ecg-option").forEach((n=>{n.onclick=()=>{"arrhythmia"===n.dataset.answer?(stopBeepLoop(),updatePatientState("arrhythmia"),playSound("success"),document.getElementById("ecg-status").innerHTML="\n\n                ✅ Diagnosis confirmed\n\n                <br><br>\n\n                Ventricular Tachycardia detected.\n\n                <br>\n\n                Prepare defibrillator.\n\n                ",setTimeout((()=>{stageCompleted()}),2e3)):(playSound("failure"),gameOver("Wrong ECG interpretation. Patient condition worsened."))}}))}let beepInterval;function beepLoop(){beepInterval=setInterval((()=>{playSound("beep")}),3e3)}function stopBeepLoop(){clearInterval(beepInterval)}